-- Each expression raises division by zero if the access rule is violated.
SELECT 1 / CASE WHEN NOT has_column_privilege('authenticated', 'public.configuracoes_salao', 'evolution_api_key', 'SELECT') THEN 1 ELSE 0 END AS salon_cannot_read_api_key;
SELECT 1 / CASE WHEN NOT has_column_privilege('authenticated', 'public.configuracoes_salao', 'evolution_api_url', 'UPDATE') THEN 1 ELSE 0 END AS salon_cannot_configure_api;
SELECT 1 / CASE WHEN has_column_privilege('authenticated', 'public.configuracoes_salao', 'whatsapp_salao', 'UPDATE') AND has_column_privilege('authenticated', 'public.configuracoes_salao', 'nome_salao', 'SELECT') THEN 1 ELSE 0 END AS salon_personal_settings_available;
SELECT 1 / CASE WHEN NOT has_table_privilege('authenticated', 'public.platform_evolution_settings', 'SELECT') AND NOT has_table_privilege('anon', 'public.platform_evolution_settings', 'SELECT') THEN 1 ELSE 0 END AS platform_credentials_private;
SELECT 1 / CASE WHEN NOT has_column_privilege('authenticated', 'public.salon_connections', 'api_token', 'SELECT') THEN 1 ELSE 0 END AS legacy_credentials_private;
SELECT 1 / CASE WHEN EXISTS (SELECT 1 FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'user_roles_single_developer' AND indexdef LIKE 'CREATE UNIQUE INDEX%') THEN 1 ELSE 0 END AS single_developer_enforced;